def _get_cache_control(
    model: Model,
    cache_retention: CacheRetention | None = None,
) -> tuple[CacheRetention, dict[str, Any] | None]:
    retention = resolve_cache_retention(cache_retention)
    if retention == "none":
        return retention, None
    compat = _get_anthropic_compat(model)
    ttl = "1h" if retention == "long" and compat.get("supports_long_cache_retention", True) else None
    cache_control: dict[str, Any] = {"type": "ephemeral"}
    if ttl:
        cache_control["ttl"] = ttl
    return retention, cache_control


def _merge_headers(
    *header_sources: dict[str, str | None] | None,
) -> dict[str, str | None]:
    merged: dict[str, str | None] = {}
    for source in header_sources:
        if source:
            merged.update(source)
    return merged


def _is_oauth_token(api_key: str) -> bool:
    return "sk-ant-oat" in api_key


def _to_claude_code_name(name: str) -> str:
    return _CC_TOOL_LOOKUP.get(name.lower(), name)


def _from_claude_code_name(name: str, tools: list[Tool] | None = None) -> str:
    if tools:
        lower_name = name.lower()
        for tool in tools:
            if tool.name.lower() == lower_name:
                return tool.name
    return name


def _convert_content_blocks(
    content: list[TextContent | ImageContent],
) -> str | list[dict[str, Any]]:
    has_images = any(c.type == "image" for c in content)
    if not has_images:
        return sanitize_surrogates("\n".join(c.text for c in content if c.type == "text"))
    blocks: list[dict[str, Any]] = []
    for block in content:
        if block.type == "text":
            blocks.append({"type": "text", "text": sanitize_surrogates(block.text)})
        else:
            blocks.append({
                "type": "image",
                "source": {
                    "type": "base64",
                    "media_type": block.mime_type,
                    "data": block.data,
                },
            })
    if not any(b["type"] == "text" for b in blocks):
        blocks.insert(0, {"type": "text", "text": "(see attached image)"})
    return blocks


def _get_anthropic_compat(model: Model) -> dict[str, Any]:
    compat = model.compat
    if compat is None or not isinstance(compat, AnthropicMessagesCompat):
        return {
            "supports_eager_tool_input_streaming": True,
            "supports_long_cache_retention": True,
        }
    return {
        "supports_eager_tool_input_streaming": compat.supports_eager_tool_input_streaming if compat.supports_eager_tool_input_streaming is not None else True,
        "supports_long_cache_retention": compat.supports_long_cache_retention if compat.supports_long_cache_retention is not None else True,
    }


def _supports_adaptive_thinking(model_id: str) -> bool:
    return any(
        tag in model_id
        for tag in (
            "opus-4-6", "opus-4.6",
            "opus-4-7", "opus-4.7",
            "opus-4-8", "opus-4.8",
            "sonnet-4-6", "sonnet-4.6",
        )
    )


def _default_thinking_display(model_id: str) -> AnthropicThinkingDisplay:
    if "opus-4-8" in model_id or "opus-4.8" in model_id:
        return "omitted"
    return "summarized"


def _map_thinking_level_to_effort(
    model: Model,
    level: str | None,
) -> AnthropicEffort:
    if level and model.thinking_level_map:
        mapped = model.thinking_level_map.get(level)
        if mapped is not None:
            return mapped  # type: ignore[return-value]
    if level:
        return ANTHROPIC_THINKING_LEVEL_TO_EFFORT.get(level, "high")  # type: ignore[return-value]
    return "high"


def _should_use_fine_grained_tool_streaming_beta(
    model: Model, context: Context
) -> bool:
    return bool(context.tools) and not _get_anthropic_compat(model).get(
        "supports_eager_tool_input_streaming", True
    )


def _normalize_tool_call_id(tool_id: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_-]", "_", tool_id)[:64]


def _map_stop_reason(reason: str) -> StopReason:
    mapped = _STOP_REASON_MAP.get(reason)
    if mapped is None:
        raise ValueError(f"Unhandled stop reason: {reason}")
    return mapped


def _convert_messages(
    messages: list[Message],
    model: Model,
    is_oauth_token: bool,
    cache_control: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    params: list[dict[str, Any]] = []
    transformed_messages = transform_messages(messages, model, _normalize_tool_call_id)

    i = 0
    while i < len(transformed_messages):
        msg = transformed_messages[i]

        if msg.role == "user":
            if isinstance(msg.content, str):
                if msg.content.strip():
                    params.append({
                        "role": "user",
                        "content": sanitize_surrogates(msg.content),
                    })
            else:
                blocks: list[dict[str, Any]] = []
                for item in msg.content:
                    if item.type == "text":
                        blocks.append({
                            "type": "text",
                            "text": sanitize_surrogates(item.text),
                        })
                    else:
                        blocks.append({
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": item.mime_type,
                                "data": item.data,
                            },
                        })
                filtered = [b for b in blocks if b["type"] != "text" or b["text"].strip()]
                if not filtered:
                    i += 1
                    continue
                params.append({"role": "user", "content": filtered})

        elif msg.role == "assistant":
            blocks = []
            for block in msg.content:
                if block.type == "text":
                    if not block.text.strip():
                        continue
                    blocks.append({
                        "type": "text",
                        "text": sanitize_surrogates(block.text),
                    })
                elif block.type == "thinking":
                    if block.redacted:
                        blocks.append({
                            "type": "redacted_thinking",
                            "data": block.thinking_signature or "",
                        })
                        continue
                    if not block.thinking.strip():
                        continue
                    if not block.thinking_signature or not block.thinking_signature.strip():
                        blocks.append({
                            "type": "text",
                            "text": sanitize_surrogates(block.thinking),
                        })
                    else:
                        blocks.append({
                            "type": "thinking",
                            "thinking": sanitize_surrogates(block.thinking),
                            "signature": block.thinking_signature,
                        })
                elif block.type == "toolCall":
                    blocks.append({
                        "type": "tool_use",
                        "id": block.id,
                        "name": _to_claude_code_name(block.name) if is_oauth_token else block.name,
                        "input": block.arguments or {},
                    })
            if blocks:
                params.append({"role": "assistant", "content": blocks})

        elif msg.role == "toolResult":
            tool_results: list[dict[str, Any]] = []
            tool_results.append({
                "type": "tool_result",
                "tool_use_id": msg.tool_call_id,
                "content": _convert_content_blocks(msg.content),
                "is_error": msg.is_error,
            })
            j = i + 1
            while j < len(transformed_messages) and transformed_messages[j].role == "toolResult":
                next_msg = transformed_messages[j]
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": next_msg.tool_call_id,
                    "content": _convert_content_blocks(next_msg.content),
                    "is_error": next_msg.is_error,
                })
                j += 1
            i = j - 1  # will be incremented at end of loop
            params.append({"role": "user", "content": tool_results})

        i += 1

    if cache_control and params:
        last = params[-1]
        if last["role"] == "user":
            content = last["content"]
            if isinstance(content, list) and content:
                last_block = content[-1]
                if last_block["type"] in ("text", "image", "tool_result"):
                    last_block["cache_control"] = cache_control
            elif isinstance(content, str):
                last["content"] = [
                    {"type": "text", "text": content, "cache_control": cache_control}
                ]

    return params


def _convert_tools(
    tools: list[Tool],
    is_oauth_token: bool,
    supports_eager_streaming: bool,
    cache_control: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not tools:
        return []
    result: list[dict[str, Any]] = []
    for idx, tool in enumerate(tools):
        schema = tool.parameters
        entry: dict[str, Any] = {
            "name": _to_claude_code_name(tool.name) if is_oauth_token else tool.name,
            "description": tool.description,
            "input_schema": {
                "type": "object",
                "properties": schema.get("properties", {}),
                "required": schema.get("required", []),
            },
        }
        if supports_eager_streaming:
            entry["eager_input_streaming"] = True
        if cache_control and idx == len(tools) - 1:
            entry["cache_control"] = cache_control
        result.append(entry)
    return result


# ---------------------------------------------------------------------------
# Client
# ---------------------------------------------------------------------------


class Error(Exception):
    """Raised when the Anthropic API call fails."""


class AnthropicClient:
    """HTTP client for the Anthropic Messages API (replaces @anthropic-ai/sdk)."""

    def __init__(
        self,
        *,
        base_url: str,
        api_key: str | None = None,
        auth_token: str | None = None,
        default_headers: dict[str, str | None] | None = None,
    ) -> None:
        self._base_url = base_url.rstrip("/")
        self._api_key = api_key
        self._auth_token = auth_token
        self._default_headers: dict[str, str | None] = default_headers or {}

    async def create_message(
        self,
        params: dict[str, Any],
        *,
        signal: Any | None = None,
        timeout: int | None = None,
        max_retries: int | None = None,
    ) -> httpx.Response:
        """POST to /v1/messages and return the raw httpx.Response."""
        headers: dict[str, str] = {}
        for k, v in self._default_headers.items():
            if v is not None:
                headers[k] = v
        if self._auth_token:
            headers["Authorization"] = f"Bearer {self._auth_token}"
        elif self._api_key:
            headers["x-api-key"] = self._api_key
        headers["anthropic-version"] = ANTHROPIC_VERSION
        headers["content-type"] = "application/json"

        url = f"{self._base_url}/v1/messages"
        timeout_s = (timeout / 1000) if timeout else 300.0

        async with httpx.AsyncClient(timeout=timeout_s) as client:
            response = await client.post(url, json=params, headers=headers)
            return response


def _create_client(
    model: Model,
    api_key: str,
    interleaved_thinking: bool,
    use_fine_grained_beta: bool,
    options_headers: dict[str, str] | None = None,
    dynamic_headers: dict[str, str] | None = None,
) -> tuple[AnthropicClient, bool]:
    needs_interleaved_beta = interleaved_thinking and not _supports_adaptive_thinking(model.id)
    beta_features: list[str] = []
    if use_fine_grained_beta:
        beta_features.append(FINE_GRAINED_TOOL_STREAMING_BETA)
    if needs_interleaved_beta:
        beta_features.append(INTERLEAVED_THINKING_BETA)

    if model.provider == "github-copilot":
        client = AnthropicClient(
            base_url=model.base_url,
            auth_token=api_key,
            default_headers=_merge_headers(
                {
                    "accept": "application/json",
                    "anthropic-dangerous-direct-browser-access": "true",
                    **({"anthropic-beta": ",".join(beta_features)} if beta_features else {}),
                },
                model.headers,
                dynamic_headers,
                options_headers,
            ),
        )
        return client, False

    if _is_oauth_token(api_key):
        client = AnthropicClient(
            base_url=model.base_url,
            auth_token=api_key,
            default_headers=_merge_headers(
                {
                    "accept": "application/json",
                    "anthropic-dangerous-direct-browser-access": "true",
                    "anthropic-beta": ["claude-code-20250219", "oauth-2025-04-20", *beta_features].join(",") if beta_features else "claude-code-20250219,oauth-2025-04-20",
                    "user-agent": f"claude-cli/{CLAUDE_CODE_VERSION}",
                    "x-app": "cli",
                },
                model.headers,
                options_headers,
            ),
        )
        return client, True

    client = AnthropicClient(
        base_url=model.base_url,
        api_key=api_key,
        default_headers=_merge_headers(
            {
                "accept": "application/json",
                "anthropic-dangerous-direct-browser-access": "true",
                **({"anthropic-beta": ",".join(beta_features)} if beta_features else {}),
            },
            model.headers,
            options_headers,
        ),
    )
    return client, False


def _build_params(
    model: Model,
    context: Context,
    is_oauth: bool,
    options: AnthropicOptions | None = None,
) -> dict[str, Any]:
    _retention, cache_control = _get_cache_control(
        model, options.cache_retention if options else None
    )
    params: dict[str, Any] = {
        "model": model.id,
        "messages": _convert_messages(
            context.messages, model, is_oauth, cache_control
        ),
        "max_tokens": (options.max_tokens if options and options.max_tokens is not None else (model.max_tokens // 3)),
        "stream": True,
    }

    if is_oauth:
        system: list[dict[str, Any]] = [{
            "type": "text",
            "text": "You are Claude Code, Anthropic's official CLI for Claude.",
            **(({"cache_control": cache_control}) if cache_control else {}),
        }]
        if context.system_prompt:
            system.append({
                "type": "text",
                "text": sanitize_surrogates(context.system_prompt),
                **(({"cache_control": cache_control}) if cache_control else {}),
            })
        params["system"] = system
    elif context.system_prompt:
        params["system"] = [{
            "type": "text",
            "text": sanitize_surrogates(context.system_prompt),
            **(({"cache_control": cache_control}) if cache_control else {}),
        }]

    if options and options.temperature is not None and not options.thinking_enabled:
        params["temperature"] = options.temperature

    if context.tools:
        compat = _get_anthropic_compat(model)
        params["tools"] = _convert_tools(
            context.tools,
            is_oauth,
            compat.get("supports_eager_tool_input_streaming", True),
            cache_control,
        )

    if model.reasoning:
        if options and options.thinking_enabled:
            display: AnthropicThinkingDisplay = (
                options.thinking_display
                if options.thinking_display is not None
                else _default_thinking_display(model.id)
            )
            if _supports_adaptive_thinking(model.id):
                params["thinking"] = {"type": "adaptive", "display"}
                if options.effort:
                    params["output_config"] = {"effort": options.effort}
            else:
                params["thinking"] = {
                    "type": "enabled",
                    "budget_tokens": options.thinking_budget_tokens or 1024,
                    "display": display,
                }
        elif options and options.thinking_enabled is False:
            params["thinking"] = {"type": "disabled"}

    if options and options.metadata:
        user_id = options.metadata.get("user_id")
        if isinstance(user_id, str):
            params["metadata"] = {"user_id": user_id}

    if options and options.tool_choice:
        if isinstance(options.tool_choice, str):
            params["tool_choice"] = {"type": options.tool_choice}
        else:
            params["tool_choice"] = options.tool_choice

    return params


