class _SseDecoderState:
    __slots__ = ("event", "data", "raw")

    def __init__(self) -> None:
        self.event: str | None = None
        self.data: list[str] = []
        self.raw: list[str] = []


class _SseEvent:
    __slots__ = ("event", "data", "raw")

    def __init__(self, event: str | None, data: str, raw: list[str]) -> None:
        self.event = event
        self.data = data
        self.raw = raw


def _flush_sse_event(state: _SseDecoderState) -> _SseEvent | None:
    if not state.event and not state.data:
        return None
    event = _SseEvent(event=state.event, data="\n".join(state.data), raw=list(state.raw))
    state.event = None
    state.data = []
    state.raw = []
    return event


def _decode_sse_line(line: str, state: _SseDecoderState) -> _SseEvent | None:
    if line == "":
        return _flush_sse_event(state)
    state.raw.append(line)
    if line.startswith(":"):
        return None
    colon_idx = line.find(":")
    if colon_idx == -1:
        field_name = line
        value = ""
    else:
        field_name = line[:colon_idx]
        value = line[colon_idx + 1 :]
        if value.startswith(" "):
            value = value[1:]
    if field_name == "event":
        state.event = value
    elif field_name == "data":
        state.data.append(value)
    return None


async def _iterate_sse_messages(lines: AsyncIterator[str]) -> AsyncIterator[_SseEvent]:
    """Parse SSE events from an async line iterator."""
    state = _SseDecoderState()
    async for line in lines:
        event = _decode_sse_line(line, state)
        if event is not None:
            yield event
    event = _flush_sse_event(state)
    if event is not None:
        yield event


async def _iterate_anthropic_events(
    response: httpx.Response,
    signal: Any | None = None,
) -> AsyncIterator[dict[str, Any]]:
    """Yield parsed Anthropic stream events from an HTTP response."""
    saw_start = False
    saw_end = False
    async for sse in _iterate_sse_messages(response.aiter_lines()):
        if getattr(signal, "aborted", False):
            raise Error("Request was aborted")
        if sse.event == "error":
            raise Error(sse.data)
        if sse.event not in _ANTHROPIC_MESSAGE_EVENTS:
            continue
        try:
            event = parse_json_with_repair(sse.data)
            if event.get("type") == "message_start":
                saw_start = True
            elif event.get("type") == "message_stop":
                saw_end = True
            yield event
        except Exception as exc:
            msg = str(exc)
            raw = "\\n".join(sse.raw)
            raise Error(
                f"Could not parse Anthropic SSE event {sse.event}: {msg}; "
                f"data={sse.data}; raw={raw}"
            ) from exc
    if saw_start and not saw_end:
        raise Error("Anthropic stream ended before message_stop")


